DO $$ DECLARE f record;d text;marker text:='PERFORM pg_advisory_xact_lock(60412026,6);';BEGIN FOR f IN SELECT oid FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN('expire_pending_bookings','set_unit_contract_state','remove_booking_units','telegram_unit_status_action','cancel_booking_with_reason','confirm_booking_transition','booking_unit_marks_unit_taken','create_booking','confirm_booking','cancel_booking','record_payment','create_contract','finance_regression_tests','finance_safety_regression_tests') LOOP SELECT pg_get_functiondef(f.oid) INTO d;IF position(marker IN d)=0 THEN d:=regexp_replace(d,'\mBEGIN\M','BEGIN '||marker,'i');EXECUTE d;END IF;END LOOP;END $$;
DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef('public.record_receipt(jsonb,text)'::regprocedure) INTO d;IF position('مرجع الحجز لا يخص العميل' IN d)=0 THEN d:=replace(d,'INSERT INTO public.receipts(id,party_id,contract_id,booking_id,paid_at,method','IF nullif(_data->>''booking_id'','''') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.bookings WHERE id=(_data->>''booking_id'')::uuid AND party_id=party AND archived_at IS NULL) THEN RAISE EXCEPTION ''مرجع الحجز لا يخص العميل'';END IF;IF amt::text IN(''NaN'',''Infinity'',''-Infinity'') OR vat::text IN(''NaN'',''Infinity'',''-Infinity'') THEN RAISE EXCEPTION ''مبلغ غير صالح'';END IF; INSERT INTO public.receipts(id,party_id,contract_id,booking_id,paid_at,method');EXECUTE d;END IF;END $$;
SELECT proname,position('pg_advisory_xact_lock(60412026,6)' IN prosrc)>0 AS serialized FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN('create_booking','record_payment','record_receipt');